using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){var go=new GameObject("edge-jitter"){hideFlags=HideFlags.HideAndDontSave};try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.startLifetime=10;m.startSpeed=0;m.maxParticles=4096;var e=ps.emission;e.enabled=false;var sh=ps.shape;sh.enabled=true;sh.shapeType=ParticleSystemShapeType.SingleSidedEdge;sh.radius=1;sh.scale=new Vector3(2,3,4);sh.radiusMode=ParticleSystemShapeMultiModeValue.Loop;sh.radiusSpeed=0;sh.randomPositionAmount=.3f;ps.useAutoRandomSeed=false;ps.randomSeed=12345;ps.Play();ps.Pause();ps.Emit(4096);var p=new ParticleSystem.Particle[4096];ps.GetParticles(p);var values=new List<object>();foreach(var v in p)values.Add(new[]{v.position.x+2,v.position.y,v.position.z});File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,positions=values}));return "Edge jitter captured";}finally{UnityEngine.Object.DestroyImmediate(go);}}}

